<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><div class="stats"><div><b><?= $pageCount ?></b><span>Pages</span></div><div><b><?= $contentCount ?></b><span>Projects & posts</span></div><div><b><?= $mediaCount ?></b><span>Media items</span></div><div><b><?= $newInquiryCount ?></b><span>New enquiries</span></div></div><section class="panel"><div class="panel-head"><h2>Recently updated</h2><a href="<?= site_url('admin/content') ?>">Manage content →</a></div><?php if (!$recent): ?><p>No content yet.</p><?php else: ?><table><thead><tr><th>Title</th><th>Type</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach ($recent as $item): ?><tr><td><?= esc($item['title']) ?></td><td><?= esc($item['type']) ?></td><td><span class="pill"><?= esc($item['status']) ?></span></td><td><?= esc($item['updated_at']) ?></td></tr><?php endforeach ?></tbody></table><?php endif ?></section><?= $this->endSection() ?>
